import redis, time, sys, itertools

OLDS, NEWS, PORTS = 6379, 6380, (6379, 6380)
tol_ms = 5000
issues = []
checked = 0

def pct(b):
    return b.decode('utf-8', 'replace') if isinstance(b, bytes) else b

for db in range(16):
    o, n = redis.Redis(port=OLDS, db=db), redis.Redis(port=NEWS, db=db)
    ok = {pct(k) for k in o.scan_iter(count=1000)}
    nk = {pct(k) for k in n.scan_iter(count=1000)}
    if ok != nk:
        issues.append(f"DB{db}: keyset differs; only-old={sorted(ok-nk)[:5]} only-new={sorted(nk-ok)[:5]}")
    for k in sorted(ok & nk):
        checked += 1
        kb = k.encode()
        to, tn = o.type(kb), n.type(kb)
        if to != tn:
            issues.append(f"DB{db} {k}: type {to} vs {tn}"); continue
        po, pn = o.pttl(kb), n.pttl(kb)
        if (po < 0) != (pn < 0):
            issues.append(f"DB{db} {k}: has-TTL mismatch {po} vs {pn}")
        elif po > 0:
            eo, en = time.time()*1000 + po, time.time()*1000 + pn
            if abs(eo - en) > tol_ms:
                issues.append(f"DB{db} {k}: expiry drift {eo-en:.0f}ms")
        if to == b'stream':
            go = {(pct(g['name']), pct(g['last-delivered-id']), g.get('entries-read'), g.get('lag'), g['pending']) for g in o.xinfo_groups(kb)}
            gn = {(pct(g['name']), pct(g['last-delivered-id']), g.get('entries-read'), g.get('lag'), g['pending']) for g in n.xinfo_groups(kb)}
            if go != gn:
                issues.append(f"DB{db} {k}: groups differ\n   old={go}\n   new={gn}")
            for gname, _, _, _, _ in go:
                co = {(pct(c['name']), c['pending']) for c in o.xinfo_consumers(kb, gname.encode())}
                cn = {(pct(c['name']), c['pending']) for c in n.xinfo_consumers(kb, gname.encode())}
                if co != cn:
                    issues.append(f"DB{db} {k}/{gname}: consumers differ {co} vs {cn}")
                peo = [(pct(e['message_id']), pct(e['consumer']), e['times_delivered']) for e in o.xpending_range(kb, gname.encode(), '-', '+', 10000)]
                pen = [(pct(e['message_id']), pct(e['consumer']), e['times_delivered']) for e in n.xpending_range(kb, gname.encode(), '-', '+', 10000)]
                if peo != pen:
                    issues.append(f"DB{db} {k}/{gname}: PEL differs ({len(peo)} vs {len(pen)} entries)")
        else:
            do, dn = o.dump(kb), n.dump(kb)
            if do == dn:
                continue
            issues.append(f"DB{db} {k}: DUMP bytes differ -> logical check")
            if not logical_equal(o, n, kb, to):
                issues.append(f"DB{db} {k}: LOGICAL VALUE DIFFERS")

def logical_equal(o, n, kb, t):
    try:
        if t == b'string':  return o.get(kb) == n.get(kb)
        if t == b'hash':    return o.hgetall(kb) == n.hgetall(kb)
        if t == b'list':    return o.lrange(kb, 0, -1) == n.lrange(kb, 0, -1)
        if t == b'set':     return o.smembers(kb) == n.smembers(kb)
        if t == b'zset':    return o.zrange(kb, 0, -1, withscores=True) == n.zrange(kb, 0, -1, withscores=True)
    except Exception as e:
        issues.append(f"    logical check error {kb}: {e}")
    return False

print(f"keys checked: {checked}")
if issues:
    print(f"ISSUES ({len(issues)}):")
    for i in issues[:40]: print(" -", i)
else:
    print("ALL CHECKS PASSED: keysets, types, values, TTLs, stream groups/PELs identical")
