import redis, time, sys

def pct(b): return b.decode('utf-8', 'replace') if isinstance(b, bytes) else b

problems = []
counts = {}
for db in range(16):
    o, n = redis.Redis(port=6379, db=db), redis.Redis(port=6380, db=db)
    ok = sorted(pct(k) for k in o.scan_iter(count=1000))
    nk = sorted(pct(k) for k in n.scan_iter(count=1000))
    if ok != nk:
        problems.append(f"DB{db} keyset mismatch: only-old={set(ok)-set(nk)} only-new={set(nk)-set(ok)}")
        continue
    counts[db] = len(ok)
    for k in ok:
        kb = k.encode()
        if o.type(kb) != n.type(kb):
            problems.append(f"DB{db} {k}: TYPE mismatch"); continue
        t = o.type(kb)
        # logical value comparison
        eq = False
        if t == b'string': eq = o.get(kb) == n.get(kb)
        elif t == b'hash': eq = o.hgetall(kb) == n.hgetall(kb)
        elif t == b'list': eq = o.lrange(kb, 0, -1) == n.lrange(kb, 0, -1)
        elif t == b'set':  eq = o.smembers(kb) == n.smembers(kb)
        elif t == b'zset': eq = o.zrange(kb, 0, -1, withscores=True) == n.zrange(kb, 0, -1, withscores=True)
        elif t == b'stream':
            eq = (o.xrange(kb, '-', '+') == n.xrange(kb, '-', '+') and
                  {(pct(g['name']), pct(g['last-delivered-id']), g.get('entries-read'), g.get('lag'), g['pending']) for g in o.xinfo_groups(kb)} ==
                  {(pct(g['name']), pct(g['last-delivered-id']), g.get('entries-read'), g.get('lag'), g['pending']) for g in n.xinfo_groups(kb)})
            for g in o.xinfo_groups(kb):
                gname = g['name']
                if {(pct(c['name']), c['pending']) for c in o.xinfo_consumers(kb, gname)} != {(pct(c['name']), c['pending']) for c in n.xinfo_consumers(kb, gname)}:
                    problems.append(f"DB{db} {k}/{pct(gname)}: consumer mismatch")
                    eq = False
                po = [(pct(e['message_id']), pct(e['consumer']), e['times_delivered']) for e in o.xpending_range(kb, gname, '-', '+', 100000)]
                pn = [(pct(e['message_id']), pct(e['consumer']), e['times_delivered']) for e in n.xpending_range(kb, gname, '-', '+', 100000)]
                if po != pn:
                    problems.append(f"DB{db} {k}/{pct(gname)}: PEL mismatch")
                    eq = False
        else:
            problems.append(f"DB{db} {k}: unexpected type {t}")
        if not eq:
            problems.append(f"DB{db} {k}: VALUE mismatch")
        # TTL: absolute expiry must be identical
        eo, en = o.pexpiretime(kb), n.pexpiretime(kb)
        if eo != en:
            problems.append(f"DB{db} {k}: EXPIRY mismatch old={eo} new={en}")

print("keys per db:", counts, "total:", sum(counts.values()))
print("problems:", len(problems))
for p in problems[:30]: print("  -", p)
print("RESULT:", "FAIL" if problems else "PASS - exact copy confirmed")
